import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/mobs/commands.md","filePath":"modules/mobs/commands.md","lastUpdated":0}`),a={name:`modules/mobs/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>主命令为 <code>/emakimobs</code>，别名 <code>/emobs</code>。不带子命令执行时输出用法提示；未知子命令同样输出用法提示。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><p>所有子命令的 <code>mob_id</code> 参数都<strong>区分大小写</strong>（按定义 id 精确匹配，不存在的 id 会提示未知生物）。</p><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/emakimobs spawn &lt;mob_id&gt; [player]</code></td><td><code>emakimobs.spawn</code></td><td>在目标玩家所在位置刷出指定生物。<code>player</code> 省略时以命令执行者为目标；控制台执行时必须指定 <code>player</code>。<code>player</code> 按名称精确匹配（<code>Bukkit.getPlayerExact</code>），玩家名不存在或离线时提示缺少目标。</td></tr><tr><td><code>/emakimobs reload</code></td><td><code>emakimobs.reload</code></td><td>重载所有生物定义、掉落表、刷新规则与目标选择器，无需重启服务器。预检发现 ERROR 时会拒绝提交并回滚到上一份内容，此时的提示数量为回滚后仍在生效的定义数。</td></tr><tr><td><code>/emakimobs list [page]</code></td><td><code>emakimobs.list</code></td><td>分页列出所有已注册的生物定义（每页 10 条，按 id 排序），标题行给出总页数、总数与当前页。<code>page</code> 省略时为 1；非正整数提示页码非法，超出总页数提示范围。</td></tr><tr><td><code>/emakimobs info &lt;mob_id&gt;</code></td><td><code>emakimobs.info</code></td><td>显示该生物的原版类型、<code>components</code> 键数、<code>ea_attributes</code> 键数、已配置的触发器列表，以及是否存在同名 <code>loot_tables/&lt;mob_id&gt;.yml</code>。</td></tr><tr><td><code>/emakimobs kill &lt;mob_id&gt; [radius]</code></td><td><code>emakimobs.admin</code></td><td>清除该 id 的受管生物。指定 <code>radius</code> 时只清除以执行者为中心、该半径内的目标，因此带半径的写法只能由玩家执行；<code>radius</code> 必须是不小于 0 的有限数值。</td></tr><tr><td><code>/emakimobs count [mob_id]</code></td><td><code>emakimobs.count</code></td><td>统计受管生物数量；省略 <code>mob_id</code> 时统计全部（消息中记作 <code>*</code>）。只统计 PDC 标记中的 id 仍在当前加载集合内的实体，<code>mob_id</code> 未注册时提示未知生物。</td></tr><tr><td><code>/emakimobs debug ...</code></td><td><code>emakimobs.debug</code></td><td>转发给模块的调试子命令（CoreLib 调试命令，模块过滤为 <code>mobs</code>）；调试处理器不可用时给出提示。</td></tr></tbody></table><p><code>count</code> 与 <code>kill</code> 通过调度器逐个实体执行，结果回投给命令执行者（玩家在自己所属线程，控制台走全局线程），执行过程中若已进入停用流程则不再回投消息。</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><p><code>emakimobs.use</code> 是整个命令的门禁：没有它时命令不会被注册为可用（<code>canUse</code> 判定失败），任何子命令都无法执行。其余权限按子命令逐个检查，缺少时提示无权限。</p><table tabindex="0"><thead><tr><th>权限</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>emakimobs.use</code></td><td><code>true</code>（所有玩家）</td><td>使用 <code>/emakimobs</code> 命令的基础权限。</td></tr><tr><td><code>emakimobs.spawn</code></td><td><code>op</code></td><td>手动刷出自定义生物。</td></tr><tr><td><code>emakimobs.reload</code></td><td><code>op</code></td><td>重载配置文件。</td></tr><tr><td><code>emakimobs.list</code></td><td><code>op</code></td><td>列出已注册的生物定义。</td></tr><tr><td><code>emakimobs.info</code></td><td><code>op</code></td><td>查看单个生物定义详情。</td></tr><tr><td><code>emakimobs.count</code></td><td><code>op</code></td><td>统计受管生物数量。</td></tr><tr><td><code>emakimobs.debug</code></td><td><code>op</code></td><td>模块调试子命令。</td></tr><tr><td><code>emakimobs.admin</code></td><td><code>op</code></td><td>管理功能，当前用于 <code>kill</code>。</td></tr></tbody></table><p>Tab 补全按执行者权限过滤子命令，并补全 <code>spawn</code> / <code>info</code> / <code>kill</code> / <code>count</code> 的 <code>mob_id</code>、<code>spawn</code> 的在线玩家名与 <code>list</code> 的页码。</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to “使用示例”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 在自己所在位置刷出精英僵尸</span></span>
<span class="line"><span>/emakimobs spawn elite_zombie</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 在玩家 Steve 所在位置刷出骨骼领主</span></span>
<span class="line"><span>/emakimobs spawn bone_lord Steve</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 分页列出已注册的生物定义</span></span>
<span class="line"><span>/emakimobs list 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查看骨骼领主的定义详情</span></span>
<span class="line"><span>/emakimobs info bone_lord</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 统计精英僵尸的存活数量</span></span>
<span class="line"><span>/emakimobs count elite_zombie</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 清除周围 32 格内的精英僵尸</span></span>
<span class="line"><span>/emakimobs kill elite_zombie 32</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 重载所有配置</span></span>
<span class="line"><span>/emakimobs reload</span></span></code></pre></div><div class="caution custom-block"><p class="custom-block-title custom-block-title-default">CAUTION</p><p><code>spawn</code> 命令刷出的生物坐标与目标玩家完全一致，建议在空旷地带测试，避免生物卡入方块。</p></div>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};